{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.45,
      "why": "Only the fully pipelined family gives 1 result/cycle, so it is the most likely to clear the 250 MSPS throughput floor: throughput = Fmax x 1. Its one-stage-per-register structure also gives the shortest combinational path and therefore the highest Fmax of the pipelined variants. The ranges bracket the accuracy requirement (W around 15-16 and N around 13-16 should reach 13 accuracy bits) while allowing the search to find the smallest W/N that still meets max_abs_err <= 2^-13, which is exactly what the min-LUT objective wants."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 0.45,
      "why": "Also 1 result/cycle, so it can meet 250 MSPS if Fmax is high enough. It uses fewer pipeline registers than plain pipelined (lower FF count, and possibly slightly lower LUT count from register merging), so it is a genuine area trade-off candidate. The m range 2..8 lets the search trade Fmax against register count; the accuracy parameters are identical to pipelined, so the same W/N window applies."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 6, "high": 8, "choices": null}
      ],
      "budget_share": 0.10,
      "why": "A small probe at the highest k values. Throughput = Fmax / (ceil(N/k)+3), so even k=8 with N=16 needs Fmax around 1.25 GHz to reach 250 MSPS, which is almost certainly out of reach on Artix-7. This slice is a cheap falsification check: if any unrolled_k point clears the throughput constraint it becomes a useful low-LUT corner, and if none do we can drop the family from later rounds with evidence rather than assumption."
    }
  ],
  "rationale": "The throughput constraint is the binding one. iterative and low-k unrolled_k cannot reach 250 MSPS because they emit one result every several cycles, so the first round concentrates on the two families that emit one result per cycle: pipelined and pipelined_m. Both compute identical bits, so accuracy depends only on data_width, n_iter, angle_guard, frac_guard and rounding; the ranges 12..20 and 8..20 are chosen to straddle the 13-bit accuracy requirement so the search can locate the smallest W/N that still satisfies max_abs_err <= 2^-13, which is what min-LUT selection will pick. angle_guard and frac_guard are opened to their full registry ranges because they can buy accuracy bits cheaply without widening the whole datapath. A 10% probe on unrolled_k at k=6..8 tests the only remaining family that could in principle hit 250 MSPS, so we do not discard it without data. This split keeps ~90% of round-1 budget on the two families that can plausibly satisfy both constraints, while still giving the hypervolume search a chance to find low-LUT corners."
}

{
  "decision": "map_front",
  "rationale": "Only `pipelined` is feasible: unrolled_k (max 9.76 MSPS) and pipelined_m (max 171 MSPS) both fall short of the 250 MSPS constraint, and `iterative` (N+3 cycles/result) cannot reach 250 MSPS at any plausible Fmax, so it is not worth budget. The feasible front is entirely pipelined and already spans accuracy_bits 13.4..19.9 (well past the HV ref of 13) but only luts 1030..2176 against an HV ref of 4000 — i.e. the front covers barely half the LUT range, leaving a large uncovered HV region toward higher-area/higher-accuracy designs. With 100 evals left in the final round and only +1.4% gain last round, the best use of the reserved budget is to let NSGA-II map the full pipelined ranges (data_width 8..28, n_iter 4..30, angle_guard -2..4, frac_guard 0..4, rounding both) seeded with the current front, extending coverage toward the 4000-LUT reference while preserving the min-LUT corner (luts=1030, accuracy_bits=13.4) that the selection rule will pick.",
  "next_plan": null
}
